"""
The venv check in utils/venv_check.py, which stops a run on a venv that has
drifted from requirements.txt. Tested on plain values, never on the real venv.
"""

from utils.venv_check import drift, message, read_pins


def test_pins_read():
    """Pins are read by normalised name, skipping comments and "# via" notes."""
    text = (
        "# generated by pip-compile\n"
        "Pytest_BDD==9.0.0\n"
        "    # via -r requirements.in\n"
        "python-dotenv==1.2.4  # trailing note\n"
    )
    assert read_pins(text) == {"pytest-bdd": "9.0.0", "python-dotenv": "1.2.4"}


def test_drift_none():
    """A venv holding exactly the pins, plus unrelated extras, has no drift."""
    pins = {"pytest": "9.1.1"}
    installed = {"pytest": "9.1.1", "pip-tools": "7.5.0"}
    assert drift(pins, installed, plugins=set()) == []


def test_drift_version():
    """A pinned package at another version is reported with both versions."""
    problems = drift({"pytest-bdd": "9.0.0"}, {"pytest-bdd": "8.1.0"}, set())
    assert problems == ["pytest-bdd: 8.1.0 installed, 9.0.0 pinned"]


def test_drift_missing():
    """A pinned package that isn't installed at all is reported."""
    problems = drift({"ruff": "0.17.1"}, {}, set())
    assert problems == ["ruff: not installed, 0.17.1 pinned"]


def test_drift_plugin():
    """An unpinned pytest plugin is reported, since pytest loads it by itself."""
    installed = {"pytest": "9.1.1", "pytest-base-url": "2.1.0"}
    plugins = {"pytest-base-url"}
    problems = drift({"pytest": "9.1.1"}, installed, plugins)
    assert problems == [
        "pytest-base-url: a pytest plugin that requirements.txt doesn't pin"
    ]


def test_message():
    """The message lists every problem and gives the commands that fix them."""
    text = message(["a: 1 installed, 2 pinned", "b: not installed, 3 pinned"])
    assert "  a: 1 installed, 2 pinned\n  b: not installed, 3 pinned" in text
    assert "pip-sync requirements.txt" in text
    assert "playwright install" in text
